package com.paitrick.blog.article.controller; import com.paitrick.blog.article.dto.*; import com.paitrick.blog.article.service.ArticleService; import com.paitrick.blog.common.response.ApiResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class ArticleController{private final ArticleService s;public ArticleController(ArticleService s){this.s=s;}@GetMapping("/articles") ApiResponse<Map<String,Object>> list(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int size){return ApiResponse.ok(s.published(Math.max(1,page),Math.min(100,Math.max(1,size))));}@GetMapping("/articles/{slug}") ApiResponse<ArticleResponse> detail(@PathVariable String slug){return ApiResponse.ok(s.detail(slug));}@GetMapping("/admin/articles") ApiResponse<Map<String,Object>> admin(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){return ApiResponse.ok(s.adminList(page,size));}@GetMapping("/admin/articles/{id}") ApiResponse<ArticleResponse> get(@PathVariable long id){return ApiResponse.ok(s.byId(id));}@PostMapping("/admin/articles") ApiResponse<ArticleResponse> create(@Valid @RequestBody ArticleRequest r){return ApiResponse.ok(s.create(r));}@PutMapping("/admin/articles/{id}") ApiResponse<ArticleResponse> update(@PathVariable long id,@Valid @RequestBody ArticleRequest r){return ApiResponse.ok(s.update(id,r));}@PostMapping("/admin/articles/{id}/publish") ApiResponse<ArticleResponse> publish(@PathVariable long id){return ApiResponse.ok(s.publish(id));}@DeleteMapping("/admin/articles/{id}") ApiResponse<Void> delete(@PathVariable long id){s.delete(id);return ApiResponse.ok(null);}}
